    'd3210000-0000-0000-0000-000000000001', 'd3220000-0000-0000-0000-000000000001'
  );
  IF v_comp_count < 15 THEN
    RAISE EXCEPTION 'Composições base não encontradas. Rode o script 04 primeiro.';
