BEGIN
  SELECT count(*) INTO v_subitens FROM orcamento_subitens
  WHERE id::text LIKE 'e11%' OR id::text LIKE 'e12%' OR id::text LIKE 'e13%'
     OR id::text LIKE 'e21%' OR id::text LIKE 'e22%' OR id::text LIKE 'e23%'
     OR id::text LIKE 'e31%' OR id::text LIKE 'e32%';
  
  IF v_subitens < 65 THEN
    RAISE WARNING 'Subitens esperados: 65. Inseridos: %', v_subitens;
  END IF;
END $$;

COMMIT;
